            # In each adjacent row above/below the bar, mark the second cell
            # of each vertical 5-pair when that pair has 5s.
            for rr in (r-1, r+1):
                if 0 <= rr < h:
                    for c in range(w):
                        if grid[rr][c] == 5:
                            # only one 3 per three-column block, centered
                            if c % 3 == 1:
                                out[rr][c] = 3
    return out
