    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    hr = next((r for r,row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg), None)
    if hr is not None:
        tile = [row[:] for row in grid[:hr]]
        if tile:
            for r in range(hr + 1, h):
                out[r] = tile[(r - hr - 1) % len(tile)][:]
        return out
    # Vertical stripe dividers: repeat the initial tile, including its stripe.
    vc = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg), None)
    if vc is not None:
        tile = [row[:vc+1] for row in grid]
        for c in range(vc+1, w):
            for r in range(h):
                out[r][c] = tile[r][(c-vc-1) % (vc+1)]
    return out
