    # In the 3-column example, periodically place the unique 3 at the center
    # of each repeated 5/5/2 pattern.
    if w == 3 and all(v in (2, 3, 5) for row in grid for v in row):
        for r in range(1, h, 3):
            if all(v == 5 for v in grid[r]):
                out[r][1] = 3
        return out

    # Repeated rows of the same uniform color indicate horizontal repetition.
    hdiv = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    if hdiv:
        d = hdiv[0]
        if len(hdiv) == 1 and d > 0:
            tile = [row[:] for row in grid[:d]]
            for r in range(d + 1, h):
                out[r] = tile[(r - d - 1) % len(tile)][:]
        return out

    # A uniform full-height column is the period marker for horizontal tiling.
    vdiv = next((c for c in range(w)
                 if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg), None)
    if vdiv is not None:
        period = vdiv + 1
        for r in range(h):
            for c in range(vdiv + 1, w):
                out[r][c] = grid[r][(c - vdiv - 1) % period]
    return out
